  app.patch('/api/orders/:id/status',{preHandler:guarded('orders.write','pos')},async(request,reply)=>{
    const u=(await resolveUser(request))!;
    const orderId=id.parse((request.params as Record<string,unknown>).id);
    const requested=z.object({status:z.enum(['accepted','preparing','ready','served','cancelled'])}).parse(request.body).status;
    const order=(await pool.query('select status,payment_status,table_id,order_number,branch_id from orders where id=$1 and business_id=$2',[orderId,u.businessId])).rows[0];
    if(!order)return reply.code(404).send({message:'Order not found.'});
    if(order.payment_status==='paid'||['completed','cancelled'].includes(order.status))return reply.code(409).send({message:'Order can no longer be updated.'});
    if(requested==='cancelled'){
      const client=await pool.connect();
      try{
        await client.query('begin');
        const locked=(await client.query('select * from orders where id=$1 and business_id=$2 for update',[orderId,u.businessId])).rows[0];
        if(!locked||locked.payment_status!=='unpaid'||locked.status==='cancelled')throw Object.assign(new Error('Only an unpaid active order can be cancelled.'),{statusCode:409});
        const lines=(await client.query('select oi.product_id,oi.quantity,p.stock,p.track_stock,p.name from order_items oi join products p on p.id=oi.product_id where oi.order_id=$1 for update of p',[orderId])).rows;
        for(const line of lines){if(!line.track_stock)continue;const restored=(await client.query('update products set stock=stock+$1,updated_at=now() where id=$2 and business_id=$3 returning stock',[line.quantity,line.product_id,u.businessId])).rows[0];await client.query("insert into stock_movements(business_id,branch_id,product_id,user_id,type,quantity,before_stock,after_stock,note) values($1,$2,$3,$4,'order_cancel',$5,$6,$7,$8)",[u.businessId,locked.branch_id,line.product_id,u.id,line.quantity,num(restored.stock)-num(line.quantity),restored.stock,`Cancelled order ${locked.order_number}`]);}
        await client.query("update orders set status='cancelled',updated_at=now() where id=$1",[orderId]);
        if(locked.table_id)await client.query("update restaurant_tables set status='available',updated_at=now() where id=$1 and business_id=$2",[locked.table_id,u.businessId]);
        await client.query("insert into audit_logs(business_id,branch_id,user_id,action,entity_type,entity_id,description) values($1,$2,$3,'order.cancel','order',$4,$5)",[u.businessId,locked.branch_id,u.id,String(orderId),`Cancelled unpaid order ${locked.order_number}`]);
        await client.query('commit');
        return {data:await orderDto(orderId,u.businessId)};
      }catch(error){await client.query('rollback');throw error}finally{client.release()}
    }
    const transitions:Record<string,string[]>={pending:['accepted'],accepted:['preparing'],preparing:['ready'],ready:['served'],served:[]};
    if(!transitions[order.status]?.includes(requested))return reply.code(409).send({message:'Invalid order status transition.'});
    await pool.query('update orders set status=$1,updated_at=now() where id=$2 and business_id=$3',[requested,orderId,u.businessId]);
    return {data:await orderDto(orderId,u.businessId)};
  });
