  const returnSchema=z.object({reason:z.string().trim().min(2).max(500),refund_method:z.enum(['original','cash','card','other']).default('original'),items:z.array(z.object({sale_item_id:z.number().int().positive(),quantity:z.coerce.number().positive()})).min(1)});
  app.get('/api/sales/:id/returns',{preHandler:guarded('reports.read','pos')},async request=>{const u=(await resolveUser(request))!,saleId=id.parse((request.params as any).id);return {data:(await pool.query('select r.*,coalesce(json_agg(ri.*) filter(where ri.id is not null),\'[]\') items from sale_returns r left join sale_return_items ri on ri.return_id=r.id where r.business_id=$1 and r.sale_id=$2 group by r.id order by r.created_at desc',[u.businessId,saleId])).rows}});
  app.post('/api/sales/:id/returns',{preHandler:guarded('inventory.write','inventory')},async(request,reply)=>{const u=(await resolveUser(request))!,saleId=id.parse((request.params as any).id),input=returnSchema.parse(request.body),client=await pool.connect();try{await client.query('begin');const sale=(await client.query('select * from sales where id=$1 and business_id=$2 for update',[saleId,u.businessId])).rows[0];if(!sale){await client.query('rollback');return reply.code(404).send({message:'Sale not found.'})}let total=0;const lines=[];for(const requested of input.items){const item=(await client.query('select si.*,p.track_stock,p.name product_name from sale_items si join products p on p.id=si.product_id where si.id=$1 and si.sale_id=$2 and p.business_id=$3',[requested.sale_item_id,saleId,u.businessId])).rows[0];if(!item)throw Object.assign(new Error('Sale item not found.'),{statusCode:422});const returned=num((await client.query('select coalesce(sum(quantity),0) quantity from sale_return_items where sale_item_id=$1',[item.id])).rows[0].quantity);if(requested.quantity>num(item.quantity)-returned)throw Object.assign(new Error(`Return quantity exceeds remaining quantity for ${item.product_name}.`),{statusCode:409});const lineTotal=num(item.unit_price)*requested.quantity;total+=lineTotal;lines.push({item,quantity:requested.quantity,total:lineTotal})}const created=(await client.query('insert into sale_returns(business_id,branch_id,sale_id,user_id,reason,refund_method,total) values($1,$2,$3,$4,$5,$6,$7) returning *',[u.businessId,u.branchId,saleId,u.id,input.reason,input.refund_method,total])).rows[0];for(const line of lines){await client.query('insert into sale_return_items(return_id,sale_item_id,product_id,quantity,unit_price,total) values($1,$2,$3,$4,$5,$6)',[created.id,line.item.id,line.item.product_id,line.quantity,line.item.unit_price,line.total]);if(line.item.track_stock){const product=(await client.query('update products set stock=stock+$1,updated_at=now() where id=$2 and business_id=$3 returning stock',[line.quantity,line.item.product_id,u.businessId])).rows[0];await client.query("insert into stock_movements(business_id,branch_id,product_id,user_id,type,quantity,before_stock,after_stock,note) values($1,$2,$3,$4,'sale_return',$5,$6,$7,$8)",[u.businessId,u.branchId,line.item.product_id,u.id,line.quantity,num(product.stock)-line.quantity,product.stock,`Return sale #${saleId}: ${input.reason}`])}}await client.query('insert into audit_logs(business_id,branch_id,user_id,action,entity_type,entity_id,description) values($1,$2,$3,\'sale.return\',\'sale\',$4,$5)',[u.businessId,u.branchId,u.id,String(saleId),`Refund ${total}: ${input.reason}`]);await client.query('commit');return reply.code(201).send({data:{...created,items:lines}})}catch(error){await client.query('rollback');throw error}finally{client.release()}});

