  app.post('/api/inventory-counts',{preHandler:guarded('inventory.write','inventory')},async(request,reply)=>{const u=(await resolveUser(request))!,reason=z.object({reason:z.string().trim().max(500).nullable().optional()}).parse(request.body).reason,client=await pool.connect();try{await client.query('begin');const count=(await client.query('insert into inventory_counts(business_id,branch_id,user_id,reason) values($1,$2,$3,$4) returning *',[u.businessId,u.branchId,u.id,reason??null])).rows[0];await client.query('insert into inventory_count_items(count_id,product_id,expected_stock) select $1,id,stock from products where business_id=$2 and track_stock=true and is_active=true',[count.id,u.businessId]);await client.query('commit');return reply.code(201).send({data:count})}catch(error){await client.query('rollback');throw error}finally{client.release()}});
  app.get('/api/inventory-counts/:id',{preHandler:guarded('inventory.read','inventory')},async(request,reply)=>{const u=(await resolveUser(request))!,countId=id.parse((request.params as any).id),count=(await pool.query('select * from inventory_counts where id=$1 and business_id=$2',[countId,u.businessId])).rows[0];if(!count)return reply.code(404).send({message:'Inventory count not found.'});return {data:{...count,items:(await pool.query('select i.*,p.name,p.sku,p.barcode,p.unit from inventory_count_items i join products p on p.id=i.product_id where i.count_id=$1 order by p.name',[countId])).rows}}});
  app.put('/api/inventory-counts/:id/items',{preHandler:guarded('inventory.write','inventory')},async(request,reply)=>{const u=(await resolveUser(request))!,countId=id.parse((request.params as any).id),input=z.object({items:z.array(z.object({product_id:z.number().int().positive(),counted_stock:z.coerce.number().nonnegative()})).min(1)}).parse(request.body);const count=(await pool.query("select 1 from inventory_counts where id=$1 and business_id=$2 and status='draft'",[countId,u.businessId])).rows[0];if(!count)return reply.code(409).send({message:'Inventory count is not editable.'});for(const item of input.items)await pool.query('update inventory_count_items set counted_stock=$1 where count_id=$2 and product_id=$3',[item.counted_stock,countId,item.product_id]);return {data:{updated:input.items.length}}});
  app.post('/api/inventory-counts/:id/confirm',{preHandler:guarded('inventory.write','inventory')},async(request,reply)=>{const u=(await resolveUser(request))!,countId=id.parse((request.params as any).id),client=await pool.connect();try{await client.query('begin');const count=(await client.query("select * from inventory_counts where id=$1 and business_id=$2 and status='draft' for update",[countId,u.businessId])).rows[0];if(!count){await client.query('rollback');return reply.code(409).send({message:'Inventory count cannot be confirmed.'})}const items=(await client.query('select i.*,p.stock,p.name from inventory_count_items i join products p on p.id=i.product_id where i.count_id=$1 and i.counted_stock is not null for update of p',[countId])).rows;for(const item of items){const before=num(item.stock),after=num(item.counted_stock),difference=after-before;if(!difference)continue;await client.query('update products set stock=$1,updated_at=now() where id=$2',[after,item.product_id]);await client.query("insert into stock_movements(business_id,branch_id,product_id,user_id,type,quantity,before_stock,after_stock,note) values($1,$2,$3,$4,$5,$6,$7,$8,$9)",[u.businessId,u.branchId,item.product_id,u.id,difference>0?'adjustment_in':'adjustment_out',Math.abs(difference),before,after,`Inventory #${countId}${count.reason?`: ${count.reason}`:''}`])}await client.query("update inventory_counts set status='confirmed',confirmed_at=now() where id=$1",[countId]);await client.query('insert into audit_logs(business_id,branch_id,user_id,action,entity_type,entity_id,description) values($1,$2,$3,\'inventory.confirm\',\'inventory_count\',$4,$5)',[u.businessId,u.branchId,u.id,String(countId),`Confirmed ${items.length} counted products`]);await client.query('commit');return {data:{id:countId,status:'confirmed'}}}catch(error){await client.query('rollback');throw error}finally{client.release()}});

